questionvariables.text:
a: rand_with_step(80, 100, 1);
b: rand_with_step(10, 30, 1)/10;
c: rand_with_step(2, 8, 1);
d: rand_with_step(5, 20, 1)/10;
pStar: float((a + c) / (b + d));
qStar: float(a - b * pStar);

a: rand_with_step(80, 100, 1);
b: rand_with_step(10, 30, 1)/10;
c: rand_with_step(2, 8, 1);
d: rand_with_step(5, 20, 1)/10;
t: rand_with_step(30, 80, 1)/10;
pOrig: float((a + c) / (b + d));
qOrig: float(a - b * pOrig);
qStar: float((d*a - b*c - b*d*t) / (b + d));
pStar: float((a - qStar) / b);

px:   rand_with_step(10, 30, 1)/10;
py:   rand_with_step(10, 30, 1)/10;
I:    rand_with_step(20, 40, 1);
xStar: float(I / (2 * px));
yStar: float(I / (2 * py));
uStar: float(xStar * yStar);
tolX: float(max(1, xStar * 0.12));
tolY: float(max(1, yStar * 0.12));

a: rand_with_step(70, 100, 1);
b: rand_with_step(8, 20, 1)/10;
c: rand_with_step(5, 20, 1);
d: rand_with_step(5, 15, 1)/10;
e: rand_with_step(5, 20, 1)/10;
qStar:   float((a - c) / (b + d + e));
pStar:   float(a - b * qStar);
qMarket: float((a - c) / (b + d));
